// Helper function to translate simulated video captions dynamically
const getTranslatedDescription = (vid: { id: string; description: string }) => {
  if (!vid) return '';
  const translations: Record<string, string> = {
    'vid-1': 'Futuristic high fashion session. Presenting Glitter Makeup for the Barcelona show! ✨ #highfashion #modamexicana #futuristic',
    'vid-2': 'CapCut - An easier edit 🎬 Under the neon lights on a humid night in Madrid. #retro #neonvibes #photomodel',
    'vid-3': 'Finances for Fashion Creators: How to optimize your sponsorship earnings and reinvest ROI into stable sessions. 📈💰 #finances #fashioninvest #growth',
    'vid-4': 'Walking along Madrid\'s Gran Vía. Sincere smile and golden sunset light 🌇 #madridoutfit #casualmodel #streetstyle',
  };
  
  if (translations[vid.id]) {
    return translations[vid.id];
  }
  
  if (vid.description) {
    let desc = vid.description;
    desc = desc.replace('¡Bienvenidos a mi canal oficial en Fashion Finances! ✨ Descubre mis looks diarios, patrocina mis desfiles y adquiere', 'Welcome to my official channel on Fashion Finances! ✨ Discover my daily looks, sponsor my fashion shows and buy')
               .replace('¡Bienvenidos a mi canal oficial en Fashion Finances!', 'Welcome to my official channel on Fashion Finances!')
               .replace('Descubre mis looks diarios', 'discover my daily looks')
               .replace('patrocina mis desfiles', 'sponsor my fashion shows')
               .replace('y adquiere', 'and acquire')
               .replace('Sesión', 'Session')
               .replace('desfile', 'fashion show')
               .replace('patrocinador', 'sponsor')
               .replace('ganancias', 'earnings')
               .replace('vídeo', 'video')
               .replace('increíble', 'amazing');
    return `[EN] ${desc}`;
  }
  return 'Premium modeling session on Fashion Finances! 📸🌟 #trend #fashionista';
};

// Helper function to render hashtags (#) and mentions (@) with styled highlights and click interactions
const renderFormattedDescription = (
  text: string,
  onHashtagClick?: (tag: string) => void,
  onMentionClick?: (username: string) => void
) => {
  if (!text) return null;
  const parts = text.split(/(\s+)/);
  return (
    <>
      {parts.map((part, i) => {
        if (part.startsWith('#') && part.length > 1) {
          const tag = part.slice(1);
          return (
            <span
              key={i}
              onClick={(e) => {
                e.stopPropagation();
                if (onHashtagClick) {
                  onHashtagClick(tag);
                } else {
                  alert(`Hashtag #${tag} activado`);
                }
              }}
              className="text-[#fe2c55] hover:text-rose-400 font-extrabold cursor-pointer transition inline-block mr-0.5 drop-shadow-xs"
            >
              {part}
            </span>
          );
        } else if (part.startsWith('@') && part.length > 1) {
          const username = part.slice(1).replace(/[^a-zA-Z0-9_]/g, '');
          return (
            <span
              key={i}
              onClick={(e) => {
                e.stopPropagation();
                if (onMentionClick) {
                  onMentionClick(username);
                } else {
                  alert(`Mención a @${username} activada`);
                }
              }}
              className="text-pink-300 hover:text-white font-extrabold cursor-pointer transition inline-block mr-0.5 underline decoration-pink-300/50 hover:decoration-white"
            >
              {part}
            </span>
          );
        }
        return part;
      })}
    </>
  );
};

