const getFashionBrandLogo = (storeId: string, storeName: string) => {
  const nameLower = (storeName || '').toLowerCase();
  
  if (nameLower.includes("balmain") || (storeId && storeId.includes("balmain"))) {
    return (
      <div className="w-full h-full rounded-full bg-white border border-slate-300 flex items-center justify-center shadow-md select-none p-0.5 overflow-hidden">
        <img src={BALMAIN_LOGO_DATA_URL} alt="Balmain Paris" className="w-full h-full object-contain rounded-full" />
      </div>
    );
  }

  if (nameLower.includes("victoria's secret") || nameLower.includes("victorias secret") || storeId === 'victorias_secret_spain') {
    return (
      <div className="w-full h-full rounded-full bg-gradient-to-tr from-pink-600 via-rose-500 to-pink-400 flex items-center justify-center text-white font-serif font-black shadow-inner select-none border border-pink-300/40 text-[13px] tracking-widest relative overflow-hidden">
        <div className="absolute inset-0 bg-radial-gradient from-white/20 to-transparent opacity-60"></div>
        <span className="relative drop-shadow-[0_1px_2px_rgba(0,0,0,0.2)]">VS</span>
      </div>
    );
  }
  
  if (nameLower.includes("l'oréal") || nameLower.includes("loreal") || storeId === 'loreal_group') {
    return (
      <div className="w-full h-full rounded-full bg-neutral-950 border-2 border-amber-500/80 flex items-center justify-center text-[#f3ca52] font-serif font-black shadow-md select-none text-[11px] tracking-wider relative">
        <span className="drop-shadow-[0_1px_1px_rgba(0,0,0,0.5)]">L'O</span>
      </div>
    );
  }
  
  if (nameLower.includes("couture elite")) {
    return (
      <div className="w-full h-full rounded-full bg-slate-900 border border-amber-500/40 flex items-center justify-center shadow-md select-none p-0.5 overflow-hidden">
        <img src={COUTURE_ELITE_LOGO_DATA_URL} alt="Couture Elite Boutique" className="w-full h-full object-cover rounded-full" />
      </div>
    );
  }

  if (nameLower.includes("carolina herrera") || storeId === 'carolina_herrera_spain' || nameLower.includes("valentinarossi_w1")) {
    return (
      <div className="w-full h-full rounded-full bg-[#faf9f6] flex items-center justify-center text-neutral-900 font-serif font-black shadow-sm select-none text-[13px] tracking-widest">
        <div className="w-full h-full rounded-full flex items-center justify-center">
          <span>CH</span>
        </div>
      </div>
    );
  }

  if (nameLower.includes("chanel")) {
    return (
      <div className="w-full h-full rounded-full bg-black border border-white/20 flex items-center justify-center text-white font-serif font-black shadow-md select-none text-[13px] tracking-widest p-0.5">
        <div className="w-full h-full rounded-full border border-white/10 flex items-center justify-center">
          <span>CC</span>
        </div>
      </div>
    );
  }

  if (nameLower.includes("gucci")) {
    return (
      <div className="w-full h-full rounded-full bg-neutral-900 border-2 border-[#156d41] flex items-center justify-center text-[#e5c158] font-serif font-black shadow-md select-none text-[13px] tracking-widest relative">
        <div className="absolute bottom-0 top-0 left-1/3 right-1/3 bg-[#b5262c] opacity-30 -z-0"></div>
        <span className="z-10 drop-shadow-[0_1px_1px_rgba(0,0,0,0.6)]">GG</span>
      </div>
    );
  }

  if (nameLower.includes("dior")) {
    return (
      <div className="w-full h-full rounded-full bg-[#fcfcfc] border border-slate-300 flex items-center justify-center text-slate-900 font-serif font-bold shadow-xs select-none text-[12px] tracking-widest">
        <span>CD</span>
      </div>
    );
  }

  if (nameLower.includes("richemont")) {
    return (
      <div className="w-full h-full rounded-full bg-neutral-950 border border-neutral-800 flex items-center justify-center text-white font-sans font-extrabold tracking-widest text-[10px] sm:text-[11px] select-none shadow-md">
        <span>RICH</span>
      </div>
    );
  }

  if (nameLower.includes("prada")) {
    return (
      <div className="w-full h-full rounded-full bg-neutral-950 border border-neutral-800 flex items-center justify-center text-white font-mono font-black shadow-md select-none text-[11px] tracking-widest">
        <span>PRDA</span>
      </div>
    );
  }

  if (nameLower.includes("versace")) {
    return (
      <div className="w-full h-full rounded-full bg-gradient-to-tr from-amber-600 via-yellow-500 to-amber-500 border border-amber-300/40 flex items-center justify-center text-white font-serif font-black shadow-md select-none text-[13px] tracking-wider">
        <span>V</span>
      </div>
    );
  }

  if (nameLower.includes("louis vuitton") || nameLower.includes("vuitton")) {
    return (
      <div className="w-full h-full rounded-full bg-[#4a3b32] border-2 border-[#c29c5a]/70 flex items-center justify-center text-[#e3be85] font-serif font-black shadow-md select-none text-[13px] tracking-widest">
        <span>LV</span>
      </div>
    );
  }

  if (nameLower.includes("hermès") || nameLower.includes("hermes") || storeId === 'hermes') {
    return (
      <div className="w-full h-full rounded-full bg-[#f37021] flex items-center justify-center text-white font-serif font-black shadow-md select-none text-[14px] border border-orange-400/30">
        <span>H</span>
      </div>
    );
  }

  if (nameLower.includes("balenciaga") || storeId === 'balenciaga') {
    return (
      <div className="w-full h-full rounded-full bg-neutral-900 border border-neutral-700 flex items-center justify-center text-white font-mono font-black shadow-md select-none text-[11px] tracking-wider">
        <span>BB</span>
      </div>
    );
  }

  if (nameLower.includes("saint laurent") || nameLower.includes("ysl") || storeId === 'ysl') {
    return (
      <div className="w-full h-full rounded-full bg-neutral-950 border border-amber-400/30 flex items-center justify-center text-[#d5af66] font-serif font-black shadow-md select-none text-[11px] tracking-tighter">
        <span>YSL</span>
      </div>
    );
  }

  if (nameLower.includes("armani")) {
    return (
      <div className="w-full h-full rounded-full bg-slate-900 flex items-center justify-center text-white font-serif font-medium shadow-md select-none text-[12px] tracking-wider border border-slate-800">
        <span>GA</span>
      </div>
    );
  }

  if (nameLower.includes("givenchy")) {
    return (
      <div className="w-full h-full rounded-full bg-[#111111] border border-neutral-800 flex items-center justify-center text-white font-serif font-semibold shadow-md select-none text-[12px] tracking-wide">
        <span>G</span>
      </div>
    );
  }

  if (nameLower.includes("burberry")) {
    return (
      <div className="w-full h-full rounded-full bg-[#dec9ab] border border-[#a18a68] flex items-center justify-center text-neutral-900 font-serif font-black shadow-md select-none text-[12px] tracking-wider">
        <span>B</span>
      </div>
    );
  }

  if (nameLower.includes("dolce")) {
    return (
      <div className="w-full h-full rounded-full bg-black flex items-center justify-center text-white font-serif font-black shadow-md select-none text-[11px] tracking-widest">
        <span>DG</span>
      </div>
    );
  }

  if (nameLower.includes("fendi")) {
    return (
      <div className="w-full h-full rounded-full bg-[#febb11] border border-yellow-600/30 flex items-center justify-center text-black font-serif font-black shadow-md select-none text-[13px] tracking-widest">
        <span>F</span>
      </div>
    );
  }

  if (nameLower.includes("cartier")) {
    return (
      <div className="w-full h-full rounded-full bg-[#8b0000] border border-red-950 flex items-center justify-center text-[#faf9f6] font-serif font-medium shadow-md select-none text-[13px] tracking-widest">
        <span>C</span>
      </div>
    );
  }

  if (nameLower.includes("zara")) {
    return (
      <div className="w-full h-full rounded-full bg-black flex items-center justify-center text-white font-sans font-black shadow-md select-none text-[11px] tracking-tighter">
        <span>ZARA</span>
      </div>
    );
  }

  if (nameLower.includes("mango")) {
    return (
      <div className="w-full h-full rounded-full bg-[#1a1a1a] flex items-center justify-center text-[#eaeaea] font-sans font-black shadow-md select-none text-[10px] tracking-widest">
        <span>MNG</span>
      </div>
    );
  }

  if (nameLower.includes("h&m") || nameLower.includes("hm")) {
    return (
      <div className="w-full h-full rounded-full bg-[#e01a22] flex items-center justify-center text-white font-sans font-black italic shadow-md select-none text-[12px]">
        <span>HM</span>
      </div>
    );
  }

  const words = storeName.split(" ");
  const initials = words.map(w => w ? w[0] : '').join("").substring(0, 2).toUpperCase();
  
  const luxuriousGradients = [
    'from-slate-700 via-slate-800 to-slate-900',
    'from-neutral-700 via-neutral-800 to-neutral-900',
    'from-stone-700 via-stone-800 to-stone-900',
    'from-rose-800 via-pink-900 to-neutral-950',
    'from-amber-800 via-yellow-900 to-amber-950',
    'from-emerald-800 via-teal-900 to-emerald-950',
    'from-blue-800 via-indigo-900 to-slate-950'
  ];
  const charSum = storeName.split('').reduce((sum, char) => sum + char.charCodeAt(0), 0);
  const selectedGradient = luxuriousGradients[charSum % luxuriousGradients.length];

  return (
    <div className={`w-full h-full rounded-full bg-gradient-to-tr ${selectedGradient} flex items-center justify-center text-white font-serif font-bold shadow-md select-none text-[12px] tracking-wider border border-white/10`}>
      <span>{initials || 'AT'}</span>
    </div>
  );
};

