  // Clean up bloated localStorage from previous redundant saved_videos keys
  useEffect(() => {
    try {
      const currentUserId = userProfile?.id;
      const keysToRemove: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('saved_videos_')) {
          const targetId = key.replace('saved_videos_', '');
          if (currentUserId && targetId !== currentUserId) {
            const val = localStorage.getItem(key);
            if (val) {
              // If it doesn't contain any custom uploaded videos, we can safely remove it to reclaim space!
              if (!val.includes('uploaded-') && !val.includes('sv-uploaded-') && !val.includes('uploaded')) {
                keysToRemove.push(key);
              }
            } else {
              keysToRemove.push(key);
            }
          }
        }
      }
      keysToRemove.forEach(key => {
        localStorage.removeItem(key);
      });
      if (keysToRemove.length > 0) {
        console.log(`[CastingLive] Cleaned up ${keysToRemove.length} redundant saved videos keys to free localStorage quota.`);
      }
    } catch (err) {
      console.error('Error cleaning up localStorage:', err);
    }
  }, [userProfile?.id]);
