  const startWebcam = async () => {
    setIsRealWebcamActive(false);
    setWebcamVideoError(false);
    try {
      // Intentamos con facingMode: "user" (cámara frontal del móvil) para selfies/live
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: { ideal: "user" },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        }
      });
      if (quickCameraVideoRef.current) {
        quickCameraVideoRef.current.srcObject = stream;
        quickCameraVideoRef.current.play().catch(() => {});
        setIsRealWebcamActive(true);
      }
    } catch (err) {
      console.warn("Could not start webcam with ideal user facingMode, trying standard constraints:", err);
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        if (quickCameraVideoRef.current) {
          quickCameraVideoRef.current.srcObject = stream;
          quickCameraVideoRef.current.play().catch(() => {});
          setIsRealWebcamActive(true);
        }
      } catch (err2) {
        console.warn("Could not start real webcam, falling back to fashion simulation camera:", err2);
        setWebcamVideoError(true);
      }
    }
  };

  const stopWebcam = () => {
    if (quickCameraVideoRef.current && quickCameraVideoRef.current.srcObject) {
      const stream = quickCameraVideoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      quickCameraVideoRef.current.srcObject = null;
    }
    setIsRealWebcamActive(false);
  };

