  const [giftExplosions, setGiftExplosions] = useState<GiftParticle[]>([]);

  const triggerTikTokGiftBurst = (giftIcon: string) => {
    // Espectáculo de confeti y lluvia de emojis desactivada a petición del usuario para mantener la visual totalmente despejada
    return;
    const particlesCount = 18;
    const confettiCount = 28;
    const newParticles: GiftParticle[] = [];
    const baseId = `burst-${Date.now()}-${Math.random()}`;

    const colors = [
      '#FF2C55', // TikTok Red/Rose
      '#00f2fe', // TikTok Cyan
      '#FFD700', // Gold
      '#39FF14', // Neon Green
      '#FF007F', // Neon Pink
      '#9D00FF', // Purple
      '#FF5722'  // Orange
    ];

    const shapes: Array<'circle' | 'square' | 'triangle'> = ['circle', 'square', 'triangle'];

    // List of custom emojis requested: white diamonds, blue diamonds, red pearls, green pearls, kisses, and hearts
    const customEmojis = [
      '💎', // diamante blanco
      '🔷', // diamante azul
      '🔴', // perla roja
      '🟢', // perla verde
      '💋', // beso
      '❤️'  // corazón
    ];

    // 1. Gift icons exploding outwards from center
    for (let i = 0; i < particlesCount; i++) {
      const angle = Math.random() * 2 * Math.PI;
      const distance = Math.random() * 160 + 80;
      
      const tx = Math.cos(angle) * distance;
      const ty = Math.sin(angle) * distance - 30; // slightly up biased
      
      const scale = Math.random() * 0.7 + 0.6; // scale 0.6 to 1.3
      const rot = Math.random() * 720 - 360; 
      const duration = Math.random() * 0.8 + 0.7; // 0.7s to 1.5s
      const delay = Math.random() * 0.12; 
      const size = Math.floor(Math.random() * 12) + 24; // 24px to 36px

      newParticles.push({
        id: `${baseId}-icon-${i}`,
        icon: giftIcon,
        tx,
        ty,
        scale,
        rot,
        duration,
        delay,
        size,
        spawnX: 50,
        spawnY: 50
      });
    }

    // 2. Custom gems, pearls, kisses, and hearts exploding outwards instead of boring solid colored shapes
    for (let i = 0; i < confettiCount; i++) {
      const angle = Math.random() * 2 * Math.PI;
      const distance = Math.random() * 210 + 90; 
      
      const tx = Math.cos(angle) * distance;
      const ty = Math.sin(angle) * distance - 10;
      
      const scale = Math.random() * 0.8 + 0.4;
      const rot = Math.random() * 1080 - 540; 
      const duration = Math.random() * 1.0 + 0.8; // 0.8s to 1.8s
      const delay = Math.random() * 0.20; 
      const size = Math.floor(Math.random() * 8) + 12; // 12px to 20px (styled larger for text/emoji visibility)
      const confettiColor = colors[Math.floor(Math.random() * colors.length)];
      const confettiShape = shapes[Math.floor(Math.random() * shapes.length)];
      const customEmoji = customEmojis[Math.floor(Math.random() * customEmojis.length)];

      newParticles.push({
        id: `${baseId}-confetti-${i}`,
        confettiColor,
        confettiShape,
        customEmoji,
        tx,
        ty,
        scale,
        rot,
        duration,
        delay,
        size,
        spawnX: 50,
        spawnY: 50
      });
    }

    setGiftExplosions(prev => [...prev, ...newParticles]);

    setTimeout(() => {
      setGiftExplosions(prev => prev.filter(p => !p.id.startsWith(baseId)));
    }, 2400);
  };

