  // Dynamic World Cities searching logic using free Nominatim API with a debounce delay
  useEffect(() => {
    if (locationSearchQuery.trim().length < 3) {
      setLocationSuggestions([]);
      return;
    }

    const delayDebounceFn = setTimeout(() => {
      setLoadingLocations(true);
      fetch(`https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&q=${encodeURIComponent(locationSearchQuery)}&limit=6&featuretype=settlement`)
        .then(res => res.json())
        .then(data => {
          if (Array.isArray(data)) {
            const formatted = data.map((item: any) => {
              const name = item.name || item.display_name.split(',')[0];
              const country = item.address?.country || '';
              return country ? `${name}, ${country}` : name;
            });
            const unique = Array.from(new Set(formatted)) as string[];
            setLocationSuggestions(unique);
          }
          setLoadingLocations(false);
        })
        .catch(err => {
          console.error("Error fetching locations from Nominatim:", err);
          setLoadingLocations(false);
        });
    }, 450);

    return () => clearTimeout(delayDebounceFn);
  }, [locationSearchQuery]);
