  const editorAudioRef = useRef<HTMLAudioElement | null>(null);

  // Active audio URL resolver
  const getActiveAudioUrl = () => {
    const allSongs = [...PRESET_SONGS, ...customUploadedSongs];
    if (soundPlayingPreviewId) {
      const song = allSongs.find(s => s.id === soundPlayingPreviewId);
      if (song) return song.url;
    }
    if (uploadMusic) {
      const song = allSongs.find(s => 
        uploadMusic === `${s.title} - ${s.artist}` || 
        uploadMusic === s.title
      );
      if (song) return song.url;
    }
    return '';
  };

  const activeAudioUrl = getActiveAudioUrl();

  // Control volume of added sound audio element
  useEffect(() => {
    if (editorAudioRef.current) {
      editorAudioRef.current.volume = addedSoundVolume / 100;
    }
  }, [addedSoundVolume]);

  // Synchronize with active video volume & muted state
  useEffect(() => {
    if (previewVideoRef.current) {
      previewVideoRef.current.muted = (originalSoundVolume === 0);
      try {
        previewVideoRef.current.volume = originalSoundVolume / 100;
      } catch (e) {}
    }
  }, [originalSoundVolume, uploadVideoUrl, tiktokSubTool]);

  // Handle playing & pausing the background audio
  useEffect(() => {
    const audio = editorAudioRef.current;
    if (!audio) return;

    if (activeAudioUrl) {
      audio.load();
      audio.volume = addedSoundVolume / 100;
      
      // If we are actively testing/previewing in list OR if the main video in editor is playing
      const video = previewVideoRef.current;
      const shouldPlay = soundPlayingPreviewId || (video && !video.paused);
      
      if (shouldPlay) {
        audio.play().catch(e => console.log("Audio auto-play error", e));
      }
    } else {
      audio.pause();
    }
  }, [activeAudioUrl, soundPlayingPreviewId]);

