  useEffect(() => {
    videoRefs.current.forEach((video, index) => {
      if (video) {
        if (index === activeVideoIndex && autoPlayEnabled && !showUploadModal) {
          video.play().catch((err) => {
            console.log("Autoplay blocked, attempting muted play:", err);
            video.muted = true;
            video.play().catch(e => console.log("Muted autoplay also blocked:", e));
          });
        } else {
          video.pause();
        }
      }
    });
  }, [activeVideoIndex, filteredVideos.length, autoPlayEnabled, showUploadModal, activeSubTab, filteredVideos[activeVideoIndex]?.id]);

  // Synchronize volume and mute states to HTML5 video elements
  useEffect(() => {
    videoRefs.current.forEach((video) => {
      if (video) {
        video.volume = volume;
        video.muted = isMuted;
      }
    });
  }, [volume, isMuted, activeVideoIndex, filteredVideos.length]);

  // Handle scroll trigger keys (ArrowUp, ArrowDown)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSlideDirection('up');
        handleNextVideo();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSlideDirection('down');
        handlePrevVideo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeVideoIndex, filteredVideos.length]);

