  const handleFeedScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const container = e.currentTarget;
    const scrollTop = container.scrollTop;
    const clientHeight = container.clientHeight;
    if (clientHeight <= 0) return;
    
    // Calculate new active index
    const snappedIdx = Math.round(scrollTop / clientHeight);
    if (snappedIdx !== activeVideoIndex && snappedIdx >= 0 && snappedIdx < filteredVideos.length) {
      setActiveVideoIndex(snappedIdx);
      // Dismiss tutorial if they start scrolling
      if (showSwipeTutorial) {
        setShowSwipeTutorial(false);
      }
    }

    // Infinite Loading: if within 2 videos of the document limit, trigger generation!
    if (scrollTop + clientHeight * 2.5 >= container.scrollHeight) {
      triggerInfiniteLoad();
    }
  };

