    if (currentVideosLength > 60) return;

    const newVideos: CastingLiveVideo[] = [];

    const storeProductsPresets = [
      { name: 'Vestido Atelier Seda Roja', price: 297.49, discount: 20, image: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&q=80&w=300', ctaText: 'Sponsorizar Artículo 👑', storeName: 'Boutique Madrid' },
      { name: 'Abrigo de Alta Costura Éthéré', price: 450.00, discount: 15, image: 'https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&q=80&w=300', ctaText: 'Patrocinar Abrigo 👑', storeName: 'Loren Luxury Boutique' },
      { name: 'Chaqueta Neón Madrid Waterproof', price: 180.00, discount: 25, image: 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&q=80&w=300', ctaText: 'Comprar en Directo 🛍️', storeName: 'Cyberpunk Neon Store' },
      { name: 'Bolso Artesanal Cuero Italiano', price: 320.00, discount: 10, image: 'https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&q=80&w=300', ctaText: 'Sponsorizar Bolso 👑', storeName: 'Finch Leather Atelier' },
      { name: 'Stiletto Cristal Swarovski', price: 590.00, discount: 30, image: 'https://images.unsplash.com/photo-1543163521-1bf539c55dd2?auto=format&fit=crop&q=80&w=300', ctaText: 'Comprar Colección 👠', storeName: 'Isabella Runway Shoes' }
    ];

