            return (
              <div 
                key={pt.id} 
                className="absolute text-center select-none"
                style={{
                  left: `${pt.left}%`,
                  bottom: `${pt.bottom}%`,
                  fontSize: `${pt.size}px`,
                  animation: `flyUpAnimation ${pt.duration}s ease-out forwards`
                }}
              >
                {pt.emoji}
              </div>
            );
